hooks.command:
f=$(python3 -c "
import json, sys
try:
    d = json.load(sys.stdin)
except Exception:
    d = {}
print((d.get('tool_response') or {}).get('filePath') or (d.get('tool_input') or {}).get('file_path') or '')
")
case "$f" in
  *.py) uv run ruff check --fix "$f" >/dev/null 2>&1; uv run ruff format "$f" >/dev/null 2>&1 ;;
esac
true
